async function fetchWeather() {
  const city = cityInputEl.value.trim();
  if (!city) return;
  lastSearchedCity = city;
  document.getElementById('suggestions').classList.remove('show');
  showLoading();
  try {
    // Step 1: OWM current (needed for lat/lon)
    const curRes = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${API_KEY}&units=metric&lang=he`);
    if (!curRes.ok) throw new Error();
    const cur = await curRes.json();
    // Step 2: Open-Meteo 10-day using lat/lon from step 1
    const { lat, lon } = cur.coord;
    const foreRes = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,weathercode&forecast_days=10&timezone=auto`);
    if (!foreRes.ok) throw new Error();
    const fore = await foreRes.json();
    hide('loading');
    renderCurrent(cur);
    renderClothing(cur);
    renderForecast(fore);
    renderTip(cur);
    // Show core results with staggered animations
    showAnim('weatherCard', 0);
    showAnim('cardActions', 60, 'flex');
    showAnim('clothingSection', 130);
    showAnim('forecastSection', 200);
    showAnim('travelTip', 270, 'flex');
    // These can run after - errors here won't break the main results
    try { renderSeasonal(cur); showAnim('seasonalSection', 340); } catch(e) { hide('seasonalSection'); }
    updateWindyMap(cur.coord.lat, cur.coord.lon, cur.timezone, cur.sys.sunrise, cur.sys.sunset);
    // Scroll to weather card after results appear - offset for fixed nav
    setTimeout(() => {
      const card = document.getElementById('weatherCard');
      const top = card.getBoundingClientRect().top + window.scrollY - 88;
      window.scrollTo({ top, behavior: 'smooth' });
    }, 120);
  } catch(e) { hide('loading'); show('errorBox'); }
}

