  const cityHe = cityNames[d.name.toLowerCase()] || d.name;
  const countryHe = countryNames[d.sys.country] || d.sys.country;
  const now = new Date();
  document.getElementById('cardCity').textContent = `📍 ${cityHe}, ${countryHe}`;
  document.getElementById('cardDate').textContent = `${hebrewDays[now.getDay()]}, ${now.getDate()} ב${hebrewMonths[now.getMonth()]}`;
