function renderForecast(data) {
  const { time, temperature_2m_max, temperature_2m_min, weathercode } = data.daily;
  const grid = document.getElementById('forecastGrid');
  grid.innerHTML = '';
  time.forEach((dateStr, i) => {
    const date = new Date(dateStr + 'T12:00:00');
    const dayName = i === 0 ? 'היום' : `יום ${hebrewDays[date.getDay()]}`;
    const dateLabel = `${date.getDate()}/${date.getMonth() + 1}`;
    const maxT = Math.round(temperature_2m_max[i]);
    const minT = Math.round(temperature_2m_min[i]);
    const icon = wmoIcons[weathercode[i]] || '🌡️';
    const card = document.createElement('div');
    card.className = 'forecast-card' + (i === 0 ? ' today' : '');
    card.innerHTML = `<div class="forecast-card__day">${dayName}<span class="forecast-card__date">${i === 0 ? '' : dateLabel}</span></div><div class="forecast-card__icon">${icon}</div><span class="forecast-card__max">${maxT}°</span><span class="forecast-card__min">${minT}°</span>`;
    grid.appendChild(card);
  });
}

function renderTip(d) {
  const temp = Math.round(d.main.temp), main = d.weather[0].main;
  const city = cityNames[d.name.toLowerCase()] || d.name;
  let icon, text;
  if (main==='Rain'||main==='Drizzle'){icon='☔';text=`<strong>קחו מטריה ל${city}!</strong> יש גשם - כדאי לתכנן אטרקציות מקורות ומוזיאונים.`;}
