function getCardTheme(d) {
  const main = d.weather[0].main;
  const isNight = d.weather[0].icon.endsWith('n');
  if (isNight)                                   return 'linear-gradient(135deg,#1e1b4b,#312e81)';
  if (main === 'Clear')                          return 'linear-gradient(135deg,#2980b9,#1a6699)';
  if (main === 'Rain' || main === 'Drizzle')     return 'linear-gradient(135deg,#546e7a,#37474f)';
  if (main === 'Thunderstorm')                   return 'linear-gradient(135deg,#263238,#37474f)';
  if (main === 'Snow')                           return 'linear-gradient(135deg,#4a9eca,#2676a0)';
  if (main === 'Clouds')                         return 'linear-gradient(135deg,#607d8b,#455a64)';
  return 'linear-gradient(135deg,var(--teal),var(--teal-dark))';
}

