function renderSeasonal(d) {
  const data = climateData[d.sys.country];
  if (!data) { hide('seasonalSection'); return; }
  const cur = new Date().getMonth();

  // Row 1: empty label + 12 month headers
  const headers = '<div class="seasonal-row-label"></div>' +
    hebrewMonthsShort.map((m, i) =>
      `<div class="month-header${i===cur?' month-header--now':''}">${m}</div>`
    ).join('');

  // Row 2: temp label + 12 temp cells
  const tempRow = '<div class="seasonal-row-label">🌡️</div>' +
    data.temps.map((t, i) =>
      `<div class="temp-cell${i===cur?' temp-cell--now':''}" style="background:${tempColor(t)}">${t}°</div>`
    ).join('');

  // Row 3: rain label + 12 rain-days cells
  const rainRow = '<div class="seasonal-row-label">🌧️</div>' +
    data.rainDays.map((days, i) => {
      const alpha = Math.min(0.55, days / 14);
      return `<div class="rain-cell${i===cur?' rain-cell--now':''}" style="background:rgba(59,130,246,${alpha.toFixed(2)})">${days > 0 ? days : '-'}</div>`;
    }).join('');

  document.getElementById('seasonalStrip').innerHTML = headers + tempRow + rainRow;

  const bestMonths = data.temps.reduce((acc, t, i) => {
    if (t >= 15 && t <= 28 && data.rainDays[i] <= 7) acc.push(hebrewMonthsShort[i]);
    return acc;
  }, []);
  document.getElementById('seasonalBest').innerHTML = bestMonths.length
    ? `החודשים המומלצים לביקור: <strong>${bestMonths.join(' · ')}</strong>`
    : '';
}

