function renderClothing(d) {
  const temp = Math.round(d.main.temp);
  const main = d.weather[0].main;
  const wind = d.wind.speed;
  const items = [];

  if (temp > 28) {
    items.push({e:'🩳', l:'מכנסיים קצרים'});
    items.push({e:'👕', l:'חולצת טי'});
    items.push({e:'🕶️', l:'משקפי שמש', c:'sun'});
  } else if (temp > 22) {
    items.push({e:'👕', l:'חולצת טי'});
    items.push({e:'👖', l:'מכנסיים'});
    items.push({e:'🕶️', l:'משקפי שמש', c:'sun'});
  } else if (temp > 15) {
    items.push({e:'👕', l:'חולצת טי'});
    items.push({e:'🧥', l:"ג'קט קל"});
    items.push({e:'👖', l:'מכנסיים ארוכים'});
  } else if (temp > 8) {
    items.push({e:'🧥', l:'מעיל'});
    items.push({e:'🧣', l:'צעיף'});
    items.push({e:'👖', l:'מכנסיים ארוכים'});
  } else {
    items.push({e:'🧥', l:'מעיל חורף'});
    items.push({e:'🧣', l:'צעיף'});
    items.push({e:'🧤', l:'כפפות', c:'snow'});
  }

  if (main === 'Rain' || main === 'Drizzle') items.push({e:'☔', l:'מטריה', c:'rain'});
  if (main === 'Snow') {
    if (!items.find(i => i.e==='🧤')) items.push({e:'🧤', l:'כפפות', c:'snow'});
    if (!items.find(i => i.e==='🧣')) items.push({e:'🧣', l:'צעיף', c:'snow'});
  }
  if (wind > 10) items.push({e:'🌬️', l:'מעיל רוח', c:'wind'});

  document.getElementById('clothingItems').innerHTML = items.map(i =>
    `<div class="clothing-tag${i.c ? ' clothing-tag--'+i.c : ''}"><span class="clothing-tag__emoji">${i.e}</span><span>${i.l}</span></div>`
  ).join('');
}

function renderDaylightBar(sunrise, sunset, tzOffset) {
  const nowUnix = Date.now() / 1000;
  const dayDur = sunset - sunrise;
  const progress = Math.max(0, Math.min(1, (nowUnix - sunrise) / dayDur));
  const isDay = nowUnix >= sunrise && nowUnix <= sunset;
  const totalHours = (dayDur / 3600).toFixed(1);

  document.getElementById('daylightFill').style.width = (progress * 100) + '%';
  document.getElementById('daylightDot').style.left = (progress * 100) + '%';
  document.getElementById('daylightSunrise').textContent = fmtLocalTime(sunrise, tzOffset);
  document.getElementById('daylightSunset').textContent = fmtLocalTime(sunset, tzOffset);
  document.getElementById('daylightHours').textContent = totalHours + ' שעות אור יום';
  document.getElementById('daylightStatus').textContent = isDay ? '🌞 עכשיו יום' : '🌙 עכשיו לילה';
}

let cityTzOffset = 0, clockInterval = null;

function updateLocalClock() {
  const el = document.getElementById('cardLocalTime');
  if (!el) return;
  const d = new Date((Date.now() / 1000 + cityTzOffset) * 1000);
  const hh = String(d.getUTCHours()).padStart(2,'0');
  const mm = String(d.getUTCMinutes()).padStart(2,'0');
  const gmtSign = cityTzOffset >= 0 ? '+' : '-';
  const gmtHours = Math.abs(Math.round(cityTzOffset / 3600));
  el.textContent = `🕐 ${hh}:${mm}  ·  GMT${gmtSign}${gmtHours}`;
}

let currentLat = null, currentLon = null, currentOverlay = 'wind';

function buildWindyUrl(lat, lon, overlay) {
  return `https://embed.windy.com/embed2.html?lat=${lat}&lon=${lon}&detailLat=${lat}&detailLon=${lon}&width=650&height=450&zoom=9&level=surface&overlay=${overlay}&product=ecmwf&menu=&message=&marker=&calendar=now&pressure=&type=map&location=coordinates&detail=&metricWind=default&metricTemp=%C2%B0C&radarRange=-1`;
}

function setWindyOverlay(overlay, btn) {
  currentOverlay = overlay;
  document.querySelectorAll('.windy-overlay-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (currentLat !== null) {
    document.getElementById('windyIframe').src = buildWindyUrl(currentLat, currentLon, overlay);
  }
}

function fmtLocalTime(unixTs, tzOffset) {
  const d = new Date((unixTs + tzOffset) * 1000);
  const h = String(d.getUTCHours()).padStart(2,'0');
  const m = String(d.getUTCMinutes()).padStart(2,'0');
  return `${h}:${m}`;
}

function uvLabel(val) {
  if (val < 3) return 'נמוך';
  if (val < 6) return 'בינוני';
  if (val < 8) return 'גבוה';
  if (val < 11) return 'גבוה מאוד';
  return 'קיצוני';
}

async function updateWindyMap(lat, lon, tzOffset, sunrise, sunset) {
  currentLat = lat;
  currentLon = lon;
  document.getElementById('windyIframe').src = buildWindyUrl(lat, lon, currentOverlay);
  renderDaylightBar(sunrise, sunset, tzOffset);
  try {
    const uvRes = await fetch(`https://api.openweathermap.org/data/2.5/uvi?lat=${lat}&lon=${lon}&appid=${API_KEY}`);
    if (uvRes.ok) {
      const uvData = await uvRes.json();
      const val = Math.round(uvData.value);
      document.getElementById('extraUV').textContent = val;
      document.getElementById('extraUVLabel').textContent = uvLabel(val);
      document.getElementById('uvWarning').style.display = val >= 6 ? 'block' : 'none';
    }
  } catch(e) {
    document.getElementById('extraUV').textContent = '--';
  }
  show('windySection');
}

